<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Str;use Symfony\Component\HttpFoundation\Response;
final class RecordAdminActivity{public function handle(Request $r,Closure $next):Response{$response=$next($r);if(!$r->isMethodSafe()&&$r->is('admin/*')&&Schema::hasTable('activity_logs')){$hidden=['password','password_confirmation','api_key','api_secret','webhook_secret','client_secret','token','secret','file','logo'];$payload=collect($r->except($hidden))->map(fn($v)=>is_scalar($v)?Str::limit((string)$v,500):'[structured]')->all();DB::table('activity_logs')->insert(['user_id'=>$r->user()?->id,'action'=>Str::limit(($r->route()?->getName()??'admin.request'),191),'route'=>$r->route()?->getName(),'method'=>$r->method(),'subject_type'=>null,'subject_id'=>collect($r->route()?->parameters()??[])->first(fn($v)=>is_scalar($v)),'changes'=>json_encode($payload,JSON_UNESCAPED_UNICODE),'ip_hash'=>hash('sha256',(string)$r->ip().config('app.key')),'correlation_id'=>(string)Str::uuid(),'response_status'=>$response->getStatusCode(),'occurred_at'=>now()]);}return $response;}}
